import os
import azure.cognitiveservices.speech as speechsdk

def get_speech_config():
    speech_key = os.environ.get("AZURE_SPEECH_KEY")
    service_region = os.environ.get("AZURE_SPEECH_REGION")
    if not speech_key or not service_region:
        raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables must be set.")
    speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=service_region)
    return speech_config

def get_audio_config(stream):
    return speechsdk.audio.AudioConfig(stream=stream)

def get_recognizer(speech_config, audio_config):
    return speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

import azure.cognitiveservices.speech as speechsdk
from dataclasses import dataclass, field
from typing import Dict, Any, Optional

@dataclass
class SpeechRecognitionConfig:
    language_code: str
    sample_rate_hz: int = 16000

@dataclass
class SpeechRecognitionResult:
    text: str
    is_final: bool
    confidence: Optional[float] = None
    reason: Optional[speechsdk.ResultReason] = None

def normalize_azure_result(azure_speech_event) -> SpeechRecognitionResult:
    if isinstance(azure_speech_event, speechsdk.SpeechRecognitionEventArgs):
        return SpeechRecognitionResult(
            text=azure_speech_event.result.text,
            is_final=azure_speech_event.result.reason == speechsdk.ResultReason.RecognizedSpeech,
            confidence=azure_speech_event.result.confidence if hasattr(azure_speech_event.result, 'confidence') else None,
            reason=azure_speech_event.result.reason
        )
    elif isinstance(azure_speech_event, speechsdk.RecognitionEventArgs):
        return SpeechRecognitionResult(
            text=azure_speech_event.result.text,
            is_final=azure_speech_event.result.reason == speechsdk.ResultReason.RecognizedSpeech,
            confidence=None, # Azure SpeechRecognitionEventArgs has confidence, RecognitionEventArgs does not always.
            reason=azure_speech_event.result.reason
        )
    else:
        raise TypeError(f"Unexpected event type: {type(azure_speech_event)}")

from speech_models import SpeechRecognitionResult

def handle_partial_results(recognition_result: SpeechRecognitionResult):
    if recognition_result.is_final:
        print(f"Final result: {recognition_result.text}")
    else:
        print(f"Partial result: {recognition_result.text}")

def process_speech_stream(results_generator):
    for result in results_generator:
        if isinstance(result, SpeechRecognitionResult):
            handle_partial_results(result)
        elif isinstance(result, Exception):
            print(f"Error in stream: {result}")
            raise result

import os
from google.cloud import translate

def translate_caption(text: str, target_language_code: str, project_id: str = None) -> str:
    if project_id is None:
        project_id = os.environ.get("GCP_PROJECT_ID")
    if not project_id:
        raise ValueError("Google Cloud Project ID must be provided or set in GCP_PROJECT_ID environment variable.")

    client = translate.TranslationServiceClient()
    location = "global"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text

    return translated_text
